def cash_round(cents):
    """
    Round nonnegative cents to the nearest five cents.
    Remainders 0, 1, 2 round down; 3, 4 round up.
    """
    remainder = cents % 5
    if remainder <= 2:
        return cents - remainder
    else:
        return cents + (5 - remainder)
```

```python
def cash_round(cents):
    """
    Round nonnegative cents to the nearest five cents.
    Remainders 0, 1, 2 round down; remainders 3, 4 round up.
    """
    if cents < 0:
        raise ValueError("cents must be nonnegative")
    remainder = cents % 5
    if remainder <= 2:
        return cents - remainder
    else:
        return cents + (5 - remainder)
```

